return {
  MOTORDRIVE = { abilityId = 78, behaviour = { chance = 100, effects = { { kind = "stat_change", stages = 1, stat = "speed" } }, expressible = false, notes = "Only triggers on Electric-type moves (including non-damaging ones like Thunder Wave), which bypass Substitute for this purpose; does not trigger if this Pokémon is otherwise immune to Electric moves. No move-type filter exists for on_hit_taken/stat_change.", scope = "self", trigger = "on_hit_taken" }, effect = "Whenever an Electric-type move hits this Pokémon, its Speed rises one stage, negating any other effect on it. This ability will not take effect if this Pokémon is immune to Electric moves. Electric moves will ignore this Pokémon's Substitute. This effect includes non-damaging moves, i.e. Thunder Wave.", effectChanges = {}, generation = "generation-iv", id = "MOTORDRIVE", name = "Motor Drive", shortEffect = "Absorbs Electric moves, raising Speed one stage.", slug = "motor-drive", speciesCount = 4 },
  MOXIE = { abilityId = 153, behaviour = { chance = 100, effects = { { kind = "stat_change", stages = 1, stat = "attack" } }, expressible = false, notes = "Triggers only when this Pokémon directly knocks out another Pokémon (ally or foe) with a move, not indirect KOs (poison, Spikes, etc.). If the knocked-out Pokémon has Mummy, this Pokémon's ability changes to Mummy without the Attack boost taking effect.", scope = "self", trigger = "on_faint" }, effect = "This Pokémon's Attack rises one stage upon knocking out another Pokémon, even a friendly Pokémon. This ability does not take effect when the Pokémon indirectly causes another Pokémon to faint, e.g. through poison or Spikes. If this Pokémon knocks out a Pokémon with Mummy, the former's ability will change without taking effect.", effectChanges = {}, generation = "generation-v", id = "MOXIE", name = "Moxie", shortEffect = "Raises Attack one stage upon KOing a Pokémon.", slug = "moxie", speciesCount = 16 },
  MULTISCALE = { abilityId = 136, behaviour = { chance = 100, effects = { { factor = 0.5, kind = "damage_taken_multiplier" } }, expressible = false, notes = "Only applies while this Pokémon is at full HP; damage_taken_multiplier has no conditional field for that.", scope = "self", trigger = "passive" }, effect = "This Pokémon takes half as much damage when it is hit having full HP.", effectChanges = {}, generation = "generation-v", id = "MULTISCALE", name = "Multiscale", shortEffect = "Halves damage taken from full HP.", slug = "multiscale", speciesCount = 3 },
  MULTITYPE = { abilityId = 121, behaviour = { chance = 100, effects = { { kind = "change_type", to = "the type matching its held Plate" } }, expressible = false, notes = "Only functions on Arceus. Its held item (Plate or not) can't be taken by Covet/Thief, removed by Knock Off, or traded by Switcheroo/Trick (those moves still deal their damage); this Pokémon also can't self-remove or self-gain an item via Fling/Switcheroo/Trick. The ability itself can't be traded (Skill Swap), copied (Role Play/Trace), disabled (Gastro Acid), or changed (Worry Seed), and Mold Breaker can't ignore it. Transforming into Arceus always yields the Normal-type form before this ability reactivates to match a held Plate. None of the item-lock/ability-lock rules are modeled.", scope = "self", trigger = "passive" }, effect = "If this Pokémon is holding an elemental Plate, its type and form change to match the Plate. This Pokémon's held item, whether or not it is a Plate, cannot be taken by Covet or Thief, nor removed by Knock Off, nor traded by Switcheroo or Trick. Covet, Thief, and Knock Off still inflict damage against this Pokémon. Unlike with Sticky Hold, this Pokémon cannot use Fling, Switcheroo, or Trick to lose its item itself, nor gain an item through Switcheroo or Trick if it does not have one. This ability has no effect for any Pokémon other than Arceus. This ability cannot be traded with Skill Swap, nor copied with Role Play or Trace, nor disabled with Gastro Acid, nor changed with Worry Seed. This Pokémon cannot use Skill Swap or Role Play to lose its ability itself. Mold Breaker cannot ignore this ability. If a Pokémon Transforms into an Arceus with this ability, it will Transform into Arceus's default, Normal-type form. If the Transforming Pokémon is holding a Plate, this ability will then activate and change the Pokémon into the corresponding form.", effectChanges = {}, generation = "generation-iv", id = "MULTITYPE", name = "Multitype", shortEffect = "Changes Arceus's type and