  MUMMY = { abilityId = 152, behaviour = { chance = 100, effects = { { kind = "other", what = "changes the attacking Pokémon's ability to Mummy" } }, expressible = false, notes = "Does not affect Multitype. If the attacker has Moxie and the contact knocks this Pokémon out, the attacker's ability still changes but without the Moxie Attack boost taking effect. No kind exists for changing another Pokémon's ability.", scope = "target", trigger = "on_contact_taken" }, effect = "Whenever a contact move hits this Pokémon, the attacking Pokémon's ability changes to Mummy. Multitype is unaffected. If a Pokémon with Moxie knocks this Pokémon out, the former's ability will change without taking effect.", effectChanges = {}, generation = "generation-v", id = "MUMMY", name = "Mummy", shortEffect = "Changes attacking Pokémon's abilities to Mummy on contact.", slug = "mummy", speciesCount = 2 },
  MYCELIUMMIGHT = { abilityId = 298, behaviour = { chance = 100, effects = { { kind = "other", what = "status moves used by this Pokémon always move last within their priority bracket" }, { kind = "other", what = "status moves used by this Pokémon ignore the target's ability" } }, expressible = false, notes = "No kind exists for altering move order within a priority bracket or for bypassing the target's ability, and only status moves are affected.", scope = "self", trigger = "on_move_used" }, effect = "The Pokémon will always act more slowly when using status moves, but these moves will be unimpeded by the Ability of the target.", effectChanges = {}, generation = "generation-ix", id = "MYCELIUMMIGHT", name = "Mycelium Might", shortEffect = "Status moves go last, but are not affected by the opponent's ability.", slug = "mycelium-might", speciesCount = 2 },
  NATURALCURE = { abilityId = 30, behaviour = { chance = 100, effects = { { kind = "other", what = "cures any major status ailment this Pokémon has when it switches out" } }, expressible = false, notes = "No 'cure own status' kind exists. If this ability was only temporarily gained during battle, the cure still applies when the Pokémon leaves before the temporary ability is lost.", scope = "self", trigger = "switch_out" }, effect = "This Pokémon is cured of any major status ailment when it is switched out for another Pokémon. If this ability is acquired during battle, the Pokémon is cured upon leaving battle before losing the temporary ability.", effectChanges = {}, generation = "generation-iii", id = "NATURALCURE", name = "Natural Cure", shortEffect = "Cures any major status ailment upon switching out.", slug = "natural-cure", speciesCount = 19 },
