  NORMALIZE = { abilityId = 96, behaviour = { chance = 100, effects = { { kind = "other", what = "forces all of this Pokemon's moves to be treated as Normal-type" } }, expressible = false, notes = "Move-type override has no matching kind (change_type only covers the bearer's own type, e.g. Protean). Edge cases not captured: variable-type moves like Hidden Power are still overridden; Weather Ball keeps its weather-based power and appearance despite being forced Normal; Thunder Wave still fails against Ghost-types because the immunity check uses the move's normal targeting rules even though the move itself is now typeless-normal.", scope = "self", trigger = "passive" }, effect = "This Pokémon's moves all act as if they were Normal-type. Moves that inflict typeless damage do so as usual. Moves of variable type, such as Hidden Power, are affected. They otherwise work as usual, however; Weather Ball, for example, is always forced to be Normal, but it still has doubled power and looks different during weather. As Thunder Wave is prevented by immunities, unlike most non-damaging moves, it does not affect Ghost-type Pokémon under the effect of this ability.", effectChanges = {}, generation = "generation-iv", id = "NORMALIZE", name = "Normalize", shortEffect = "Makes the Pokémon's moves all act Normal-type.", slug = "normalize", speciesCount = 2 },
  OBLIVIOUS = { abilityId = 12, behaviour = { chance = 100, effects = { { kind = "status_immunity", status = "infatuation" } }, expressible = false, notes = "Also grants immunity to the move Captivate specifically; that is not a status condition and has no matching effect kind. Existing infatuation is cured immediately if the Pokemon gains this ability mid-battle.", scope = "self", trigger = "passive" }, effect = "This Pokémon cannot be infatuated and is immune to Captivate. If a Pokémon is infatuated and acquires this ability, its infatuation is cleared.", effectChanges = {}, generation = "generation-iii", id = "OBLIVIOUS", name = "Oblivious", shortEffect = "Prevents infatuation and protects against Captivate.", slug = "oblivious", speciesCount = 26 },
