  PICKPOCKET = { abilityId = 124, behaviour = { chance = 100, effects = { { kind = "other", what = "steals the attacker's held item if this Pokemon is not already holding one" } }, expressible = false, notes = "No effect kind models item theft. Only the last hit of a multi-hit move triggers it; cannot steal if it faints from the hit, if it already holds an item, or (when this Pokemon is wild) from a trained Pokemon. Can steal from a Substitute user but not while its own Substitute is up.", scope = "target", trigger = "on_contact_taken" }, effect = "Whenever a move makes contact with this Pokémon, if it does not have a held item, it steals the attacker's held item. This Pokémon cannot steal upon being knocked out. It can steal if the attacker has a Substitute, but cannot steal when its own Substitute is hit. If a move hits multiple times, only the last hit triggers this ability. If this Pokémon is wild, it cannot steal from a trained Pokémon.", effectChanges = {}, generation = "generation-v", id = "PICKPOCKET", name = "Pickpocket", shortEffect = "Steals attacking Pokémon's held items on contact.", slug = "pickpocket", speciesCount = 16 },
